"use client"

/**
 * niko-table — created by Semir N. (Semkoo, https://github.com/Semkoo) with AI assistance.
 *
 * Before reporting anything: please check the changelog first.
 *  - In-repo: ./CHANGELOG.md
 *  - Docs site: https://niko-table.com/changelog
 *
 * Found a bug or have a fix? Open an issue or PR on GitHub so other
 * users (and future LLMs reading this code) benefit:
 * https://github.com/Semkoo/niko-table-registry
 */

/**
 * A dropdown menu component that allows users to toggle the visibility of table columns.
 * It uses a popover to display a list of columns with checkboxes.
 *
 * Two opt-in extensions:
 *   - `lockedColumnIds`: include columns marked `enableHiding: false` in the
 *     list, but render them disabled (always-on, can't toggle).
 *   - `onReset` + `resetLabel`: render a Reset button below a separator.
 *
 * Tuned for large column counts (200+): rows are a memoized component, the
 * search filter runs at this layer (so non-matching rows skip rendering
 * entirely), and `lockedColumnIds` is consulted via a `Set` for O(1) lookups.
 *
 * For drag-to-reorder, see `TableViewDndMenu` — it lives in a separate file
 * so consumers who don't need DnD don't pay the `@dnd-kit/*` bundle cost.
 */

import type { RowData } from "@tanstack/react-table"
import { Check, ChevronsUpDown, RotateCcw, Settings2 } from "lucide-react"
import * as React from "react"
import { Button } from "@/components/niko-table/primitives/button"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/niko-table/primitives/command"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/niko-table/primitives/popover"
import { cn } from "@/lib/utils"
import { formatLabel } from "../lib/format"

import type { DataTableColumn, DataTableInstance } from "../types"
function getColumnTitle<TData extends RowData>(
  column: DataTableColumn<TData, unknown>,
): string {
  return column.columnDef.meta?.label ?? formatLabel(column.id)
}

export interface TableViewMenuProps<TData extends RowData> {
  table: DataTableInstance<TData>
  className?: string
  onColumnVisibilityChange?: (columnId: string, isVisible: boolean) => void
  /**
   * Column ids that should appear in the menu but cannot be toggled off.
   * Useful for columns the table marks `enableHiding: false` but the
   * consumer still wants visible in the column list (typically with a
   * Reset to Defaults affordance below).
   */
  lockedColumnIds?: string[]
  /**
   * When provided, renders a Reset button at the bottom of the menu.
   * Useful when paired with persisted column preferences so users can
   * revert to defaults.
   */
  onReset?: () => void
  /** Label for the reset button. Defaults to "Reset to defaults". */
  resetLabel?: string
  /**
   * Replaces the default toolbar button.
   *
   * Same `trigger` contract the sibling filters already expose
   * (`TableColumnActions`, `TableDateFilter`, `TableFacetedFilter`), so a
   * consumer that needs a different trigger shape — a header-sized bare icon
   * beside a column title, for instance — composes one instead of waiting for
   * a boolean per shape.
   */
  trigger?: React.ReactNode
}

interface MenuRowProps<TData extends RowData> {
  column: DataTableColumn<TData, unknown>
  isLocked: boolean
  isVisible: boolean
  onToggle: (columnId: string) => void
}

const MenuRow = React.memo(function MenuRow<TData extends RowData>({
  column,
  isLocked,
  isVisible,
  onToggle,
}: MenuRowProps<TData>) {
  return (
    <CommandItem
      data-disabled={isLocked ? "" : undefined}
      onSelect={() => {
        if (isLocked) return
        onToggle(column.id)
      }}
    >
      <span className={cn("truncate", isLocked && "text-muted-foreground")}>
        {getColumnTitle(column)}
      </span>
      <Check
        className={cn(
          "ml-auto size-4 shrink-0",
          isLocked ? "opacity-50" : isVisible ? "opacity-100" : "opacity-0",
        )}
      />
    </CommandItem>
  )
}) as <TData extends RowData>(props: MenuRowProps<TData>) => React.ReactElement

export function TableViewMenu<TData extends RowData>({
  table,
  onColumnVisibilityChange,
  lockedColumnIds,
  onReset,

  trigger,
  resetLabel,
}: TableViewMenuProps<TData>) {
  // Controlled search. cmdk's built-in filter hides non-matching `CommandItem`s
  // but still renders all of them — at 200+ columns that's the bottleneck.
  // Filtering at this layer means non-matching rows skip rendering entirely.
  const [search, setSearch] = React.useState("")

  // O(1) lookups instead of O(m) `.includes()` per row.
  const lockedSet = React.useMemo(
    () => new Set(lockedColumnIds ?? []),
    [lockedColumnIds],
  )

  const columns = React.useMemo(
    () =>
      table
        .getAllColumns()
        .filter(
          column =>
            typeof column.accessorFn !== "undefined" &&
            (column.getCanHide() || lockedSet.has(column.id)),
        ),
    // Depend on the column set, not just the (stable) table ref.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [table, table.options.columns, lockedSet],
  )

  const visibleColumns = React.useMemo(() => {
    const q = search.trim().toLowerCase()
    if (!q) return columns
    return columns.filter(c => getColumnTitle(c).toLowerCase().includes(q))
  }, [columns, search])

  // Stable callback so memoized rows skip re-render on keystrokes.
  const onToggle = React.useCallback(
    (columnId: string) => {
      const column = table.getColumn(columnId)
      if (!column) return
      const newVisibility = !column.getIsVisible()
      column.toggleVisibility(newVisibility)
      onColumnVisibilityChange?.(columnId, newVisibility)
    },
    [table, onColumnVisibilityChange],
  )

  return (
    <Popover>
      <PopoverTrigger asChild>
        {trigger ?? (
          <Button
            aria-label="Toggle columns"
            role="combobox"
            variant="outline"
            size="sm"
            className="ml-auto hidden h-8 lg:flex"
          >
            <Settings2 />
            View
            <ChevronsUpDown className="ml-auto opacity-50" />
          </Button>
        )}
      </PopoverTrigger>
      <PopoverContent align="end" className="w-fit p-0">
        <Command shouldFilter={false}>
          <CommandInput
            placeholder="Search columns..."
            value={search}
            onValueChange={setSearch}
          />
          <CommandList>
            <CommandEmpty>No columns found.</CommandEmpty>
            <CommandGroup>
              {visibleColumns.map(column => (
                <MenuRow
                  key={column.id}
                  column={column}
                  isLocked={lockedSet.has(column.id)}
                  isVisible={column.getIsVisible()}
                  onToggle={onToggle}
                />
              ))}
            </CommandGroup>
          </CommandList>
          {onReset ? (
            <>
              <div className="border-t" />
              <Button
                variant="ghost"
                size="sm"
                className="w-full justify-start gap-2 rounded-none text-muted-foreground"
                onClick={onReset}
              >
                <RotateCcw className="size-4" />
                {resetLabel ?? "Reset to defaults"}
              </Button>
            </>
          ) : null}
        </Command>
      </PopoverContent>
    </Popover>
  )
}

/**
 * @required displayName is required for auto feature detection
 * @see "feature-detection.ts"
 */

TableViewMenu.displayName = "TableViewMenu"

"use client"

/**
 * Niko Table's popover primitive, React Aria build. Radix-shaped API
 * (`Popover open onOpenChange`, `PopoverTrigger asChild`, `PopoverContent
 * align side sideOffset`) on shadcn's React Aria `PopoverTrigger` (React Aria
 * `DialogTrigger`, which owns the open state) and `Popover`.
 *
 * `PopoverTrigger asChild` hands the press to its child: the Button primitive
 * (or shadcn's Button) takes it directly, a plain element through `Pressable`.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import {
  OverlayTriggerStateContext,
  Pressable,
  type Placement,
} from "react-aria-components"

import {
  Popover as PopoverPrimitive,
  PopoverTrigger as PopoverRoot,
} from "@/components/ui/popover"

type Side = "top" | "right" | "bottom" | "left"
type Align = "start" | "center" | "end"
type PressableChild = React.ComponentProps<typeof Pressable>["children"]

function toPlacement(side: Side, align: Align): Placement {
  if (align === "center") return side
  if (side === "top" || side === "bottom") return `${side} ${align}`
  return `${side} ${align === "start" ? "top" : "bottom"}`
}

function useDataState() {
  const isOpen = React.useContext(OverlayTriggerStateContext)?.isOpen ?? false
  return isOpen ? "open" : "closed"
}

function Popover({
  open,
  defaultOpen,
  onOpenChange,
  children,
}: {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Radix option; React Aria popovers are always modal. */
  modal?: boolean
  children?: React.ReactNode
}) {
  return (
    <PopoverRoot
      isOpen={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {children}
    </PopoverRoot>
  )
}

function PopoverTrigger({
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const state = { "data-state": useDataState() }
  // Slot: the trigger's own props (refs, handlers, classes) merge onto the child.
  const child =
    asChild && React.isValidElement<object>(children) ? (
      React.cloneElement(children, mergeProps(children.props, props, state))
    ) : (
      <button type="button" {...props} {...state}>
        {children}
      </button>
    )
  // A host element (a plain <button>, <a>) cannot take React Aria's press
  // itself, so Pressable gives it one. A component child (the Button
  // primitive, shadcn's Button) takes it directly; wrapping it too would
  // register the press twice.
  return typeof child.type === "string" ? (
    <Pressable>{child as PressableChild}</Pressable>
  ) : (
    child
  )
}

function PopoverContent({
  align = "center",
  side = "bottom",
  sideOffset = 4,
  alignOffset = 0,
  id,
  className,
  children,
  ...props
}: Omit<
  React.ComponentProps<typeof PopoverPrimitive>,
  | "children"
  | "className"
  | "placement"
  | "offset"
  | "crossOffset"
  | "isOpen"
  | "onOpenChange"
  | "triggerRef"
> & {
  align?: Align
  side?: Side
  sideOffset?: number
  alignOffset?: number
  /** Radix puts it on the popup; React Aria's popover takes no `id`. */
  id?: string
  className?: string
  children?: React.ReactNode
}) {
  return (
    <PopoverPrimitive
      {...props}
      placement={toPlacement(side, align)}
      offset={sideOffset}
      crossOffset={alignOffset}
      className={className}
      data-state={useDataState()}
    >
      {id ? (
        <div id={id} className="contents">
          {children}
        </div>
      ) : (
        children
      )}
    </PopoverPrimitive>
  )
}

export { Popover, PopoverContent, PopoverTrigger }

"use client"

/**
 * Niko Table's button primitive, React Aria build: shadcn's React Aria
 * `Button` behind the Radix `Button` API Niko Table calls it with (native
 * `<button>` props, `variant`, `size`, `asChild`).
 *
 * - `onClick` goes to React Aria's `onClick`, its alias of `onPress`: a real
 *   MouseEvent on click and a synthesized click for keyboard and screen-reader
 *   presses, so `stopPropagation()` / `shiftKey` keep working.
 * - `disabled` becomes `isDisabled`.
 * - Everything else (title, tabIndex, role, aria-*, key and mouse handlers) goes
 *   on the `<button>` through React Aria's `render`, as on a native button.
 *   React Aria's Button would drop those attributes and stop key events.
 *
 * Overlay triggers (`PopoverTrigger asChild` and the rest) hand their press to
 * this button, so an `asChild` trigger's child must be this Button (or
 * shadcn's), as with shadcn's own React Aria triggers.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import type { VariantProps } from "class-variance-authority"

import {
  Button as ButtonPrimitive,
  buttonVariants,
} from "@/components/ui/button"
import { cn } from "@/lib/utils"

type OnPressClick = React.ComponentProps<typeof ButtonPrimitive>["onClick"]

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  if (
    asChild &&
    React.isValidElement<React.HTMLAttributes<HTMLElement>>(children)
  ) {
    // Slot: the child element is the button (e.g. a link styled as one); its
    // own handlers and refs compose with the button's.
    return React.cloneElement(children, {
      ...mergeProps(children.props, { "data-slot": "button" }, props),
      className: cn(
        buttonVariants({ variant, size }),
        className,
        children.props.className,
      ),
    } as React.HTMLAttributes<HTMLElement>)
  }

  const { ref, id, type, slot, disabled, onClick, onMouseDown, ...native } =
    props
  return (
    <ButtonPrimitive
      ref={ref}
      id={id}
      type={type}
      slot={slot}
      variant={variant}
      size={size}
      className={className}
      isDisabled={disabled}
      onClick={onClick as OnPressClick}
      render={domProps => (
        <button
          {...mergeProps(domProps, native)}
          onMouseDown={event => {
            // React Aria's press handler stops every left mousedown; a native
            // button lets it bubble (the grid selects cells on mousedown).
            event.stopPropagation = () => {}
            domProps.onMouseDown?.(event)
            delete (event as Partial<typeof event>).stopPropagation
            onMouseDown?.(event)
          }}
        />
      )}
    >
      {children}
    </ButtonPrimitive>
  )
}

export { Button }

"use client"

/**
 * Niko Table's command primitive, React Aria build: shadcn's own React Aria
 * `command` (an `Autocomplete` over a `Menu`) under the cmdk-shaped API Niko
 * Table calls.
 *
 * - `CommandInput` `value` / `onValueChange` drive the `Autocomplete` input.
 *   The input must be a child of `Command` (directly or inside a fragment).
 * - `shouldFilter={false}` keeps every item (the caller filters);
 *   `filter(value, search)` is used as a match when it returns more than 0.
 *   Otherwise shadcn's `contains` filter applies (substring, not cmdk's fuzzy
 *   score, and items keep their order).
 * - `CommandEmpty` inside `CommandList` becomes the menu's empty state.
 * - `CommandItem` filters on `value` (or its text, as cmdk does) plus
 *   `keywords`; `onSelect(value)` runs on press or Enter.
 * - Anything that is not an item, group or separator goes in `CommandPanel`.
 *   Items inside a panel are plain rows outside the menu's arrow-key
 *   navigation (Tab, Enter and Space reach them).
 */
import * as React from "react"
import { Header } from "react-aria-components"

import {
  Command as AriaCommand,
  CommandEmpty,
  CommandGroup as AriaCommandGroup,
  CommandInput as AriaCommandInput,
  CommandItem as AriaCommandItem,
  CommandList as AriaCommandList,
  CommandSeparator,
} from "@/components/ui/command"
import { cn } from "@/lib/utils"

const LoopContext = React.createContext(false)
const PanelContext = React.createContext(false)

type CommandInputProps = Omit<
  React.ComponentProps<typeof AriaCommandInput>,
  "value" | "onChange"
> & {
  ref?: React.Ref<HTMLInputElement>
  value?: string
  onValueChange?: (value: string) => void
}

/** Elements of `type` among `children`, looking inside fragments. */
function findAll(
  children: React.ReactNode,
  type: React.ElementType,
): React.ReactElement[] {
  return React.Children.toArray(children).flatMap(child => {
    if (!React.isValidElement<{ children?: React.ReactNode }>(child)) return []
    if (child.type === type) return [child]
    return child.type === React.Fragment
      ? findAll(child.props.children, type)
      : []
  })
}

/** `children` without elements of `type`, looking inside fragments. */
function without(
  children: React.ReactNode,
  type: React.ElementType,
): React.ReactNode {
  return React.Children.map(children, child => {
    if (!React.isValidElement<{ children?: React.ReactNode }>(child))
      return child
    if (child.type === type) return null
    return child.type === React.Fragment
      ? React.cloneElement(
          child,
          undefined,
          without(child.props.children, type),
        )
      : child
  })
}

/** The text a node renders, as cmdk reads an item's value from its content. */
function textOf(node: React.ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node)
  if (Array.isArray(node)) return node.map(textOf).join("")
  if (React.isValidElement<{ children?: React.ReactNode }>(node))
    return textOf(node.props.children)
  return ""
}

function Command({
  shouldFilter = true,
  filter,
  loop = false,
  className,
  children,
}: {
  shouldFilter?: boolean
  filter?: (value: string, search: string) => number
  loop?: boolean
  className?: string
  children?: React.ReactNode
}) {
  const input = findAll(children, CommandInput)[0]?.props as
    CommandInputProps | undefined
  const [ownValue, setOwnValue] = React.useState("")

  return (
    <LoopContext.Provider value={loop}>
      <AriaCommand
        className={className}
        inputValue={input?.value ?? ownValue}
        onInputChange={next => {
          setOwnValue(next)
          input?.onValueChange?.(next)
        }}
        filter={
          !shouldFilter
            ? () => true
            : filter
              ? (text, search) => filter(text, search) > 0
              : undefined
        }
      >
        {children}
      </AriaCommand>
    </LoopContext.Provider>
  )
}

function CommandInput({
  value: _value,
  onValueChange: _onValueChange,
  ...props
}: CommandInputProps) {
  // `value` / `onValueChange` are read by `Command`, which owns the input.
  return <AriaCommandInput {...props} />
}

function CommandList({
  className,
  children,
}: {
  className?: string
  children?: React.ReactNode
}) {
  const loop = React.useContext(LoopContext)
  const empty = findAll(children, CommandEmpty)[0]
  return (
    <div
      className="contents"
      onKeyDown={stopReplayedKeys}
      onKeyUp={stopReplayedKeys}
    >
      <AriaCommandList
        aria-label="Suggestions"
        shouldFocusWrap={loop}
        // cmdk never closes its popover; Niko Table closes it where needed.
        shouldCloseOnSelect={false}
        className={className}
        renderEmptyState={empty ? () => empty : undefined}
      >
        {without(children, CommandEmpty)}
      </AriaCommandList>
    </div>
  )
}

// shadcn's item appends its own check icon (for `data-checked`, which Niko
// Table does not use); Niko Table's items draw their own.
const ITEM_CLASS = "[&>svg:last-child]:hidden"

function CommandItem({
  value,
  keywords,
  onSelect,
  disabled = false,
  className,
  children,
}: {
  value?: string
  keywords?: string[]
  onSelect?: (value: string) => void
  disabled?: boolean
  className?: string
  children?: React.ReactNode
}) {
  const inPanel = React.useContext(PanelContext)
  const itemValue = (value ?? textOf(children)).trim()
  const select = () => onSelect?.(itemValue)

  if (inPanel) {
    return (
      <div
        role="button"
        tabIndex={disabled ? -1 : 0}
        aria-disabled={disabled || undefined}
        data-slot="command-item"
        className={cn(
          "relative flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden select-none hover:bg-muted focus-visible:bg-muted aria-disabled:pointer-events-none aria-disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4",
          className,
        )}
        onClick={disabled ? undefined : select}
        onKeyDown={event => {
          if (disabled || (event.key !== "Enter" && event.key !== " ")) return
          event.preventDefault()
          select()
        }}
      >
        {children}
      </div>
    )
  }

  return (
    <AriaCommandItem
      textValue={[itemValue, ...(keywords ?? [])].join(" ")}
      isDisabled={disabled}
      onAction={select}
      className={cn(ITEM_CLASS, className)}
    >
      {children}
    </AriaCommandItem>
  )
}

function CommandGroup({
  className,
  children,
}: {
  className?: string
  children?: React.ReactNode
}) {
  // A section holding only a panel would be filtered out as empty, so a
  // group around a panel renders the panel as a top-level menu node.
  if (findAll(children, CommandPanel).length > 0)
    return React.Children.map(children, child =>
      React.isValidElement<{ className?: string }>(child) &&
      child.type === CommandPanel
        ? React.cloneElement(child, {
            className: cn("overflow-hidden p-1 text-foreground", className),
          })
        : child,
    )
  return <AriaCommandGroup className={className}>{children}</AriaCommandGroup>
}

function stopReplayedKeys(event: React.KeyboardEvent) {
  // Autocomplete replays every key typed in the input on the list (focus
  // stays in the input). The replay bubbles to window, where Niko Table's
  // single-key shortcuts (S, F) would fire. Escape still bubbles so the
  // popover closes; keys pressed in a panel (focus there) go on, so
  // drag-and-drop keyboard sensors on the document still get them.
  if (event.key !== "Escape" && event.target !== document.activeElement)
    event.stopPropagation()
}

function stopTab(event: React.KeyboardEvent) {
  // The menu's Tab handler moves focus out of the list; Tab moves between
  // the panel's own controls instead.
  if (event.key === "Tab") event.stopPropagation()
}

/**
 * Free-form content inside a `CommandList` (a calendar, a drag-and-drop
 * list). React Aria menus drop anything that is not a menu node, so this
 * renders it as a non-focusable menu node. A passthrough on Radix and Base UI.
 */
function CommandPanel({
  className,
  children,
}: {
  className?: string
  children: React.ReactNode
}) {
  return (
    <Header
      role="presentation"
      className={className}
      onKeyDown={stopTab}
      // The menu moves focus to its first item when focus enters it.
      onFocus={event => event.stopPropagation()}
    >
      <PanelContext.Provider value>{children}</PanelContext.Provider>
    </Header>
  )
}

export {
  Command,
  CommandInput,
  CommandList,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandPanel,
  CommandSeparator,
}
